    Wq2,Wk2,Wv2,Wo2,_,_=H[(l2,h2)]
    OV=Wo1@Wv1  # d x d
    nOV=np.linalg.norm(OV)
    k=np.linalg.norm(Wk2@OV)/(np.linalg.norm(Wk2)*nOV)
    q=np.linalg.norm(Wq2@OV)/(np.linalg.norm(Wq2)*nOV)
    v=np.linalg.norm(Wv2@OV)/(np.linalg.norm(Wv2)*nOV)
    return q,k,v
